import torch,json
P='model.language_model.'
labels={'month_offset':[' January',' February',' March',' April',' May',' June',' July',' August',' September',' October',' November',' December'],'fraction_role':[' numerator',' denominator'],'product_sign':[' positive',' negative'],'color_mix':[' red',' blue',' yellow',' green',' purple',' orange'],'letter_case':[' uppercase',' lowercase'],'tense_classification':[' past',' present',' future']}
U=W('lm_head.weight'); n=W(P+'norm.weight'); vv=[]
for words in labels.values():vv.append(torch.nn.functional.normalize(U[[encode(w)[-1] for w in words]]*n,dim=1).mean(0))
V=torch.nn.functional.normalize(torch.stack(vv),dim=1);del U
res={k:[] for k in labels}
for l in [32,36,40,44,46,48,50,51,53,55,57,59,61]:
 D=W(f'{P}layers.{l}.mlp.down_proj.weight'); s=V@D/D.norm(dim=0)
 for j,k in enumerate(labels):
  a,ix=s[j].topk(8);res[k]+=[(float(v),l,int(i)) for v,i in zip(a,ix)]
for k in res: print(k,sorted(res[k],reverse=True)[:14])
json.dump(res,open('/work/more_ranks.json','w'))
